 report+=['## Jours refusés et diagnostics',table(['Variante','SMT sans cible','SMT RR<1','SMT absent','H2 annulé','Sans confirm.','Ambigu','Biais sans cible','Biais RR<1','Hasards sans cible*','Hasards RR<1*'],rows),'* Comptages sur 1 000 portefeuilles ; ce ne sont pas des dates distinctes. Les catégories complètes incluent les biais neutres dans [diagnostics.json](results/diagnostics.json). Les journées sans cible sont publiées explicitement pour la stratégie et les deux témoins.']
