 report += [table(['Variante','Coûts USD','Win rate','Wilson95','Série pertes max','Pire jour USD','5 meilleurs gains USD','R nul'],rows),table(['Variante','Gaps non nuls','RR réel<1 H1','Sorties immédiates','Stop+TP même bougie','Gap absolu max pts'],gaprows),'Les excursions MAE/MFE des journaux ne sont que les extrêmes observables conservés par le simulateur hors ordre intraminute inconnu : elles ne certifient pas le chemin des prix. Le rapport utilise les drawdowns clôturés. Les journaux `ledger_1_*` et `ledger_2_*` incluent `ecart_ouverture`, prix remplis, stops, objectifs, frais, résolution et R réel.']
 rows=[]
